WITH monthly AS (SELECT substr(o.order_date,1,7) ym,SUM(i.line_revenue) revenue FROM fact_orders o JOIN fact_order_items i USING(order_id) WHERE o.order_status NOT IN ('cancelled','returned') GROUP BY 1) SELECT ym,revenue,LAG(revenue) OVER(ORDER BY ym) prior_month,revenue-LAG(revenue) OVER(ORDER BY ym) change,AVG(revenue) OVER(ORDER BY ym ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) rolling_3m,SUM(revenue) OVER(ORDER BY ym) running_revenue FROM monthly;
SELECT customer_id,SUM(line_revenue) revenue FROM fact_orders JOIN fact_order_items USING(order_id) WHERE order_status NOT IN ('cancelled','returned') GROUP BY customer_id HAVING SUM(line_revenue)>(SELECT AVG(customer_revenue) FROM (SELECT SUM(line_revenue) customer_revenue FROM fact_order_items GROUP BY order_id));
